import java.io.*;
import java.util.*;

public class Main {
    static byte[] buf;
    static int pos;

    static void skip() {
        while (pos < buf.length && buf[pos] <= ' ') pos++;
    }

    static String next() {
        skip();
        int start = pos;
        while (pos < buf.length && buf[pos] > ' ') pos++;
        return new String(buf, start, pos - start);
    }

    static long nextLong() {
        skip();
        boolean neg = buf[pos] == '-';
        if (neg) pos++;
        long r = 0;
        while (pos < buf.length && buf[pos] >= '0' && buf[pos] <= '9') r = r * 10 + (buf[pos++] - '0');
        return neg ? -r : r;
    }

    static int nextInt() {
        return (int) nextLong();
    }

    public static void main(String[] args) throws IOException {
        buf = System.in.readAllBytes();
        int n = nextInt();
        long[] a = new long[n];
        long z = 0;
        for (int i = 0; i < n; i++) {
            a[i] = nextLong();
            if (a[i] > 0) z += a[i];
        }
        if (z % 2 == 0) {
            System.out.println(z);
            return;
        }
        // Odd: drop the smallest positive odd, or add the negative odd closest to zero.
        boolean hasPos = false, hasNeg = false;
        long minPos = 0, maxNeg = 0;
        for (long x : a) {
            if (x % 2 == 0) continue;
            if (x > 0 && (!hasPos || x < minPos)) {
                minPos = x;
                hasPos = true;
            }
            if (x < 0 && (!hasNeg || x > maxNeg)) {
                maxNeg = x;
                hasNeg = true;
            }
        }
        long best = 0;
        if (hasPos) best = Math.max(best, z - minPos);
        if (hasNeg) best = Math.max(best, z + maxNeg);
        System.out.println(best);
    }
}

package main

import (
	"fmt"
	"io"
	"os"
)

var data []byte
var pos int

func skip() {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
}

func next() string {
	skip()
	start := pos
	for pos < len(data) && data[pos] > ' ' {
		pos++
	}
	return string(data[start:pos])
}

func nextInt() int64 {
	skip()
	neg := false
	if pos < len(data) && data[pos] == '-' {
		neg = true
		pos++
	}
	var r int64
	for pos < len(data) && data[pos] >= '0' && data[pos] <= '9' {
		r = r*10 + int64(data[pos]-'0')
		pos++
	}
	if neg {
		return -r
	}
	return r
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	n := int(nextInt())
	a := make([]int64, n)
	var z int64
	for i := range a {
		a[i] = nextInt()
		if a[i] > 0 {
			z += a[i]
		}
	}
	if z%2 == 0 {
		fmt.Println(z)
		return
	}
	// Odd: drop the smallest positive odd, or add the negative odd closest to zero.
	hasPos, hasNeg := false, false
	var minPos, maxNeg int64
	for _, x := range a {
		if x%2 == 0 {
			continue
		}
		if x > 0 && (!hasPos || x < minPos) {
			minPos, hasPos = x, true
		}
		if x < 0 && (!hasNeg || x > maxNeg) {
			maxNeg, hasNeg = x, true
		}
	}
	var best int64
	if hasPos {
		best = max(best, z-minPos)
	}
	if hasNeg {
		best = max(best, z+maxNeg)
	}
	fmt.Println(best)
}
